+static tap_packet_status
+follow_utp_tap_listener(void *tapdata, packet_info *pinfo, epan_dissect_t *edt _U_, const void *data)
+{
+  /* Similar to the TCP follow tap listener in that it reorders the
+   * datagrams, but simpler in that we only have sequence numbers, not
+   * byte offsets and thus overlapping data, etc. isn't an issue.
+   */
+  follow_record_t *follow_record;
+  follow_info_t *follow_info = (follow_info_t *)tapdata;
+  tvbuff_t * tvb = (tvbuff_t*)data;
+  /* We could include it with data, or we can get the info from the
+   * conversation, using the packet_info to find it.
+   */
+
+  utp_info_t* p_utp_info = (utp_info_t *)p_get_proto_data(pinfo->pool, pinfo, proto_bt_utp, 0);
+
+  gboolean is_server; /* P2P, server is first side seen (initiator if SYN). */
+  guint16 sequence = p_utp_info->seq;
+  guint32 data_length = tvb_captured_length(tvb);
+
+  if (p_utp_info->type == ST_SYN) {
+    /* SYN packets have no data, but advance the expected sequence number. */
+    sequence++;
+  }
+
+  if (follow_info->client_port == 0) {
+      follow_info->client_port = pinfo->srcport;
+      copy_address(&follow_info->client_ip, &pinfo->src);
+      follow_info->server_port = pinfo->destport;
+      copy_address(&follow_info->server_ip, &pinfo->dst);
+  }
+
+  is_server = !(addresses_equal(&follow_info->client_ip, &pinfo->src) && follow_info->client_port == pinfo->srcport);
+
+  /* If we have stored fragments in the other direction, check to see if ack_nr
+   * check to see if ack_nr has gotten past the missing segments we're waiting
+   * on. If so, that means the receiving host saw them but they're not in the
+   * capture file and never will be.
+   */
+  if (follow_info->fragments[!is_server] != NULL) {
+    while (check_follow_fragments(follow_info, !is_server, p_utp_info->ack, pinfo->fd->num, TRUE));
+  }
+
+  /* If this is the first segment of the stream, initialize the next expected
+   * sequence number. If there is data, it will be added below. (The value
+   * for SYN packets has been incremented above; other packets without data
+   * do not increment the sequence number according to BEP-29.)
+   */
+  if (follow_info->bytes_written[is_server] == 0 && follow_info->seq[is_server] == 0) {
+    follow_info->seq[is_server] = sequence;
+  }
+
+  /* Now ignore segments with no new data, either because empty, or because
+   * the sequence number has been seen / ACKed. Unlike with TCP, we don't have
+   * to worry about overlapping segments.
+   */
+  if (data_length == 0 || LT_SEQ16(sequence, follow_info->seq[is_server])) {
+    return TAP_PACKET_DONT_REDRAW;
+  }
+
+  follow_record = g_new0(follow_record_t, 1);
+  follow_record->is_server = is_server;
+  follow_record->packet_num = pinfo->fd->num;
+  follow_record->abs_ts = pinfo->fd->abs_ts;
+  follow_record->seq = sequence;
+  follow_record->data = g_byte_array_sized_new(data_length);
+  follow_record->data = g_byte_array_append(follow_record->data,
+                                            tvb_get_ptr(tvb, 0, -1),
+                                            data_length);
+
+  if (sequence == follow_info->seq[is_server]) {
+    follow_info->seq[is_server] = (guint16)(follow_info->seq[is_server] + 1);
+    follow_info->bytes_written[is_server] += follow_record->data->len;
+    follow_info->payload = g_list_prepend(follow_info->payload, follow_record);
+
+    /* Check to see if previous out of order fragments now fit. */
+    while (check_follow_fragments(follow_info, is_server, 0, pinfo->fd->num, FALSE));
+  } else {
+    /* Out of order packet. Expect preceding segments, so hold on to this. */
+    follow_info->fragments[is_server] = g_list_append(follow_info->fragments[is_server], follow_record);
+  }
+  return TAP_PACKET_DONT_REDRAW;
+}
